import subprocess, os

def run(args, input_data=None, timeout=3):
    try:
        p = subprocess.run(["./executable"]+args, input=input_data, capture_output=True, timeout=timeout)
        return p.returncode, p.stdout, p.stderr
    except subprocess.TimeoutExpired as e:
        return "TIMEOUT", (e.stdout or b""), (e.stderr or b"")

def write(path, content):
    open(path,"w").write(content)

tests = []

# Tag handling
write("/tmp/t1.php", 'hello world')  # no tags
write("/tmp/t2.php", '<?php echo "hi";')  # no closing
write("/tmp/t3.php", 'Hello <?php echo "world"; ?>!')
write("/tmp/t4.php", '<?= "short echo"; ?>')
write("/tmp/t5.php", '<? echo "short tag"; ?>')  # short_open_tag On
write("/tmp/t6.php", '<?php echo "a"; ?> plain <?php echo "b"; ?>')

for f in ["t1","t2","t3","t4","t5","t6"]:
    rc,out,err = run([f"/tmp/{f}.php"])
    print(f"FILE {f} RC={rc} OUT={out!r} ERR={err!r}")

# stdin handling
for code in [b'<?php echo "stdin hi";', b'hello', b'<?= "x"; ?>']:
    rc,out,err = run([], code)
    print(f"STDIN {code!r} RC={rc} OUT={out!r} ERR={err!r}")

# -r handling with tags? -r should not use tags, but what if tags included?
for code in ['echo "hi";', '<?php echo "hi";', 'echo "hi"; ?>']:
    rc,out,err = run(["-r", code])
    print(f"-r {code!r} RC={rc} OUT={out!r} ERR={err!r}")
PY"}

