class Parser:
    def __init__(self, tokens, file="Command line code"):
        self.toks = tokens
        self.pos = 0
        self.file = file

    def peek(self, n=0):
        if self.pos + n < len(self.toks):
            return self.toks[self.pos+n]
        return Token('EOF','',0)

    def next(self):
        t = self.peek()
        self.pos += 1
        return t

    def expect(self, typ, val=None):
        t = self.next()
        if t.typ != typ or (val is not None and t.val != val):
            raise PhpParseError(f'syntax error, unexpected {t.val!r}', self.file, t.line)
        return t

    def match(self, typ, val=None):
        t = self.peek()
        if t.typ == typ and (val is None or t.val == val):
            self.pos += 1
            return t
        return None

    def parse_program(self):
        stmts = []
        while self.peek().typ != 'EOF':
            # Skip extra semicolons?
            if self.match('OP',';'):
                continue
            # Handle closing tag? In -r mode, ?> switches? For now, treat ?> as HTML? Actually in -r, ?> + HTML should be handled at higher level
            # For block parsing, '}' ends?
            if self.peek().typ == 'OP' and self.peek().val == '}':
                break
            stmts.append(self.parse_statement())
        return stmts

    def parse_block(self):
        self.expect('OP','{')
        stmts = []
        while not (self.peek().typ=='OP' and self.peek().val=='}'):
            if self.peek().typ == 'EOF':
                raise PhpParseError('syntax error, unexpected end of file', self.file, self.peek().line)
            if self.match('OP',';'):
                continue
            stmts.append(self.parse_statement())
        self.expect('OP','}')
        return Block(stmts)

    def parse_statement(self):
        t = self.peek()
        if t.typ == 'ID':
            low = t.val.lower()
            if low == 'echo':
                return self.parse_echo()
            if low in ('if',):
                return self.parse_if()
            if low == 'while':
                return self.parse_while()
            if low == 'do':
                return self.parse_do()
            if low == 'for':
                return self.parse_for()
            if low == 'foreach':
                return self.parse_foreach()
            if low == 'switch':
                return self.parse_switch()
            if low == 'function':
                return self.parse_function_def()
            if low == 'class':
                return self.parse_class_def()
            if low in ('interface','trait','enum'):
                # Skip? Parse as class-like but ignore for now
                return self.parse_class_def()
            if low == 'return':
                return self.parse_return()
            if low == 'break':
                return self.parse_break()
            if low == 'continue':
                return self.parse_continue()
            if low == 'try':
                return self.parse_try()
            if low == 'throw':
                return self.parse_throw()
            if low in ('include','include_once','require','require_once'):
                return self.parse_include_stmt()
            if low == 'global':
                return self.parse_global()
            if low == 'static':
                # Could be static var or static call? Check next
                # If next is VAR or ID with =? then static var
                # Else expression
                # Peek ahead
                if self.peek(1).typ == 'VAR' or (self.peek(1).typ=='ID'):
                    # Might be static var declaration inside function
                    return self.parse_static()
                # else fall through to expr
            if low == 'unset':
                return self.parse_unset()
            if low in ('echo','print'):
                # print as statement? Actually print is expression, but handle
                pass
            if low == 'declare':
                return self.parse_declare()
            if low == 'namespace':
                return self.parse_namespace()
            if low == 'use':
                # use for closure or trait? Simplify: skip to ;
                return self.parse_use()
        # Check for { block?
        if t.typ=='OP' and t.val=='{':
            b = self.parse_block()
            return b
        # Otherwise expression statement
        expr = self.parse_expr()
        # Expect ; (or allow missing at EOF? PHP requires ; but be lenient)
        if not self.match('OP',';'):
            # Allow } or EOF without ;? Check
            if self.peek().typ != 'EOF' and not (self.peek().typ=='OP' and self.peek().val in ('}','EOF')):
                # If next is closing php tag? Not here
                raise PhpParseError(f'syntax error, unexpected {self.peek().val!r}', self.file, self.peek().line)
        return ExprStmt(expr, t.line)

    def parse_echo(self):
        t = self.expect('ID')
        # echo expr, expr, ...
        exprs = []
        # echo can be 'echo' or 'echo('? Actually echo is not function, but allow parens?
        exprs.append(self.parse_expr())
        while self.match('OP',','):
            exprs.append(self.parse_expr())
        self.match('OP',';')
        return EchoStmt(exprs, t.line)

    def parse_if(self):
        t = self.expect('ID')
        self.expect('OP','(')
        cond = self.parse_expr()
        self.expect('OP',')')
        # Then branch: either block or single statement, also handle : endif syntax?
        if self.match('OP',':'):
            # Alternative syntax: if(): ... endif;
            stmts = []
            elifs = []
            else_b = None
            while True:
                pt = self.peek()
                if pt.typ=='ID' and pt.val.lower() in ('elseif','else','endif'):
                    break
                if pt.typ=='EOF':
                    break
                if self.match('OP',';'):
                    continue
                stmts.append(self.parse_statement())
            then_b = Block(stmts)
            while True:
                pt = self.peek()
                if pt.typ=='ID' and pt.val.lower()=='elseif':
                    self.next()
                    self.expect('OP','(')
                    c2 = self.parse_expr()
                    self.expect('OP',')')
                    self.expect('OP',':')
                    s2 = []
                    while True:
                        pt2 = self.peek()
                        if pt2.typ=='ID' and pt2.val.lower() in ('elseif','else','endif'):
                            break
                        if pt2.typ=='EOF':
                            break
                        if self.match('OP',';'):
                            continue
                        s2.append(self.parse_statement())
                    elifs.append((c2, Block(s2)))
                else:
                    break
            if self.peek().typ=='ID' and self.peek().val.lower()=='else':
                self.next()
                self.expect('OP',':')
                s3=[]
                while True:
                    pt3=self.peek()
                    if pt3.typ=='ID' and pt3.val.lower()=='endif':
                        break
                    if pt3.typ=='EOF':
                        break
                    if self.match('OP',';'):
                        continue
                    s3.append(self.parse_statement())
                else_b = Block(s3)
            # expect endif
            if self.peek().typ=='ID' and self.peek().val.lower()=='endif':
                self.next()
                self.match('OP',';')
            return IfStmt(cond, then_b, elifs, else_b, t.line)
        else:
            # Normal
            if self.peek().typ=='OP' and self.peek().val=='{':
                then_b = self.parse_block()
            else:
                then_b = Block([self.parse_statement()])
            elifs=[]
            else_b=None
            # Check elseif/else
            while self.peek().typ=='ID' and self.peek().val.lower() in ('elseif','else'):
                if self.peek().val.lower()=='elseif':
                    self.next()
                    self.expect('OP','(')
                    c2=self.parse_expr()
                    self.expect('OP',')')
                    if self.peek().typ=='OP' and self.peek().val=='{':
                        b2=self.parse_block()
                    else:
                        b2=Block([self.parse_statement()])
                    elifs.append((c2,b2))
                else:
                    self.next()
                    if self.peek().typ=='ID' and self.peek().val.lower()=='if':
                        # else if
                        self.next()
                        self.expect('OP','(')
                        c2=self.parse_expr()
                        self.expect('OP',')')
                        if self.peek().typ=='OP' and self.peek().val=='{':
                            b2=self.parse_block()
                        else:
                            b2=Block([self.parse_statement()])
                        elifs.append((c2,b2))
                    else:
                        if self.peek().typ=='OP' and self.peek().val=='{':
                            else_b=self.parse_block()
                        else:
                            else_b=Block([self.parse_statement()])
                        break
            return IfStmt(cond, then_b, elifs, else_b, t.line)

    def parse_while(self):
        t=self.expect('ID')
        self.expect('OP','(')
        cond=self.parse_expr()
        self.expect('OP',')')
        if self.peek().typ=='OP' and self.peek().val=='{':
            body=self.parse_block()
        elif self.peek().typ=='OP' and self.peek().val==':':
            self.next()
            stmts=[]
            while not (self.peek().typ=='ID' and self.peek().val.lower()=='endwhile'):
                if self.peek().typ=='EOF':
                    break
                if self.match('OP',';'):
                    continue
                stmts.append(self.parse_statement())
            if self.peek().typ=='ID':
                self.next()
            self.match('OP',';')
