                # Else expression
                # Peek ahead
                if self.peek(1).typ == 'VAR' or (self.peek(1).typ=='ID'):
                    # Might be static var declaration inside function
                    return self.parse_static()
                # else fall through to expr
            if low == 'unset':
                return self.parse_unset()
            if low in ('echo','print'):
                # print as statement? Actually print is expression, but handle
                pass
            if low == 'declare':
                return self.parse_declare()
            if low == 'namespace':
                return self.parse_namespace()
            if low == 'use':
                # use for closure or trait? Simplify: skip to ;
                return self.parse_use()
        # Check for { block?
        if t.typ=='OP' and t.val=='{':
            b = self.parse_block()
            return b
        # Otherwise expression statement
        expr = self.parse_expr()
        # Expect ; (or allow missing at EOF? PHP requires ; but be lenient)
        if not self.match('OP',';'):
            # Allow } or EOF without ;? Check
            if self.peek().typ != 'EOF' and not (self.peek().typ=='OP' and self.peek().val in ('}','EOF')):
                # If next is closing php tag? Not here
                raise PhpParseError(f'syntax error, unexpected {self.peek().val!r}', self.file, self.peek().line)
        return ExprStmt(expr, t.line)

    def parse_echo(self):
        t = self.expect('ID')
        # echo expr, expr, ...
        exprs = []
        # echo can be 'echo' or 'echo('? Actually echo is not function, but allow parens?
        exprs.append(self.parse_expr())
        while self.match('OP',','):
            exprs.append(self.parse_expr())
        self.match('OP',';')
        return EchoStmt(exprs, t.line)

    def parse_if(self):
        t = self.expect('ID')
        self.expect('OP','(')
        cond = self.parse_expr()
        self.expect('OP',')')
        # Then branch: either block or single statement, also handle : endif syntax?
        if self.match('OP',':'):
            # Alternative syntax: if(): ... endif;
            stmts = []
            elifs = []
            else_b = None
            while True:
                pt = self.peek()
                if pt.typ=='ID' and pt.val.lower() in ('elseif','else','endif'):
                    break
                if pt.typ=='EOF':
                    break
                if self.match('OP',';'):
                    continue
                stmts.append(self.parse_statement())
            then_b = Block(stmts)
            while True:
                pt = self.peek()
                if pt.typ=='ID' and pt.val.lower()=='elseif':
                    self.next()
                    self.expect('OP','(')
                    c2 = self.parse_expr()
                    self.expect('OP',')')
                    self.expect('OP',':')
                    s2 = []
                    while True:
                        pt2 = self.peek()
                        if pt2.typ=='ID' and pt2.val.lower() in ('elseif','else','endif'):
                            break
                        if pt2.typ=='EOF':
                            break
                        if self.match('OP',';'):
                            continue
                        s2.append(self.parse_statement())
                    elifs.append((c2, Block(s2)))
                else:
                    break
            if self.peek().typ=='ID' and self.peek().val.lower()=='else':
                self.next()
                self.expect('OP',':')
                s3=[]
                while True:
                    pt3=self.peek()
                    if pt3.typ=='ID' and pt3.val.lower()=='endif':
                        break
                    if pt3.typ=='EOF':
                        break
                    if self.match('OP',';'):
                        continue
                    s3.append(self.parse_statement())
                else_b = Block(s3)
            # expect endif
            if self.peek().typ=='ID' and self.peek().val.lower()=='endif':
                self.next()
                self.match('OP',';')
            return IfStmt(cond, then_b, elifs, else_b, t.line)
        else:
            # Normal
            if self.peek().typ=='OP' and self.peek().val=='{':
                then_b = self.parse_block()
            else:
                then_b = Block([self.parse_statement()])
            elifs=[]
            else_b=None
            # Check elseif/else
            while self.peek().typ=='ID' and self.peek().val.lower() in ('elseif','else'):
                if self.peek().val.lower()=='elseif':
                    self.next()
                    self.expect('OP','(')
                    c2=self.parse_expr()
                    self.expect('OP',')')
                    if self.peek().typ=='OP' and self.peek().val=='{':
                        b2=self.parse_block()
                    else:
                        b2=Block([self.parse_statement()])
                    elifs.append((c2,b2))
                else:
                    self.next()
                    if self.peek().typ=='ID' and self.peek().val.lower()=='if':
                        # else if
                        self.next()
                        self.expect('OP','(')
                        c2=self.parse_expr()
                        self.expect('OP',')')
                        if self.peek().typ=='OP' and self.peek().val=='{':
                            b2=self.parse_block()
                        else:
                            b2=Block([self.parse_statement()])
                        elifs.append((c2,b2))
                    else:
                        if self.peek().typ=='OP' and self.peek().val=='{':
                            else_b=self.parse_block()
                        else:
                            else_b=Block([self.parse_statement()])
                        break
            return IfStmt(cond, then_b, elifs, else_b, t.line)

    def parse_while(self):
        t=self.expect('ID')
        self.expect('OP','(')
        cond=self.parse_expr()
        self.expect('OP',')')
        if self.peek().typ=='OP' and self.peek().val=='{':
            body=self.parse_block()
        elif self.peek().typ=='OP' and self.peek().val==':':
            self.next()
            stmts=[]
            while not (self.peek().typ=='ID' and self.peek().val.lower()=='endwhile'):
                if self.peek().typ=='EOF':
                    break
                if self.match('OP',';'):
                    continue
                stmts.append(self.parse_statement())
            if self.peek().typ=='ID':
                self.next()
            self.match('OP',';')
            body=Block(stmts)
        else:
            body=Block([self.parse_statement()])
        return WhileStmt(cond, body, t.line)

    def parse_do(self):
        t=self.expect('ID')
        if self.peek().typ=='OP' and self.peek().val=='{':
            body=self.parse_block()
        else:
            body=Block([self.parse_statement()])
        # expect while
        if not (self.peek().typ=='ID' and self.peek().val.lower()=='while'):
            raise PhpParseError('syntax error, unexpected '+self.peek().val, self.file, self.peek().line)
        self.next()
        self.expect('OP','(')
        cond=self.parse_expr()
        self.expect('OP',')')
        self.match('OP',';')
        return DoWhileStmt(body, cond, t.line)

    def parse_for(self):
        t=self.expect('ID')
        self.expect('OP','(')
        init=[]
        if not (self.peek().typ=='OP' and self.peek().val==';'):
            init.append(self.parse_expr())
            while self.match('OP',','):
                init.append(self.parse_expr())
        self.expect('OP',';')
        cond=None
        if not (self.peek().typ=='OP' and self.peek().val==';'):
            # Could be multiple? Actually for cond is single expr (but allow comma?)
            cond=self.parse_expr()
            # Handle comma? Keep as last?
        self.expect('OP',';')
        step=[]
        if not (self.peek().typ=='OP' and self.peek().val==')'):
            step.append(self.parse_expr())
            while self.match('OP',','):
                step.append(self.parse_expr())
        self.expect('OP',')')
        if self.peek().typ=='OP' and self.peek().val=='{':
            body=self.parse_block()
        elif self.peek().typ=='OP' and self.peek().val==':':
            self.next()
            stmts=[]
            while not (self.peek().typ=='ID' and self.peek().val.lower()=='endfor'):
                if self.peek().typ=='EOF':
                    break
                if self.match('OP',';'):
                    continue
                stmts.append(self.parse_statement())
            if self.peek().typ=='ID':
                self.next()
            self.match('OP',';')
            body=Block(stmts)
        else:
            body=Block([self.parse_statement()])
        return ForStmt(init, cond, step, body, t.line)

    def parse_foreach(self):
        t=self.expect('ID')
        self.expect('OP','(')
        arr_expr=self.parse_expr()
        # expect 'as'
        if not (self.peek().typ=='ID' and self.peek().val.lower()=='as'):
            raise PhpParseError('syntax error, unexpected '+self.peek().val, self.file, self.peek().line)
        self.next()
        # Check for key => value or value
        # Need to parse variable (could be $k => $v or $v)
        # Look ahead for =>?
        # Parse first var
        first = self.parse_expr()  # should be var
        key_var=None
        val_var=None
        by_ref=False
        if self.match('OP','=>'):
            key_var=first
            # Check for &?
            if self.match('OP','&'):
                by_ref=True
            val_var=self.parse_expr()
        else:
            # first is val_var, check if by_ref? Actually syntax is foreach($a as &$v) -> & before?
            # Our first already parsed, but if it was & $v? Our parse_expr would handle & as unary? Need to handle.
            # For simplicity, if first is UnaryExpr with & then extract
            if isinstance(first, UnaryExpr) and first.op=='&':
                by_ref=True
                val_var=first.expr
            else:
                val_var=first
                # Check if next is? No, already consumed
        self.expect('OP',')')
        if self.peek().typ=='OP' and self.peek().val=='{':
            body=self.parse_block()
        elif self.peek().typ=='OP' and self.peek().val==':':
            self.next()
            stmts=[]
            while not (self.peek().typ=='ID' and self.peek().val.lower()=='endforeach'):
                if self.peek().typ=='EOF':
                    break
                if self.match('OP',';'):
                    continue
                stmts.append(self.parse_statement())
            if self.peek().typ=='ID':
                self.next()
            self.match('OP',';')
            body=Block(stmts)
        else:
            body=Block([self.parse_statement()])
        # Extract var names
        def get_var_name(e):
            if isinstance(e, VarExpr):
                return e.name
            if isinstance(e, UnaryExpr) and e.op=='&' and isinstance(e.expr, VarExpr):
                return e.expr.name
            return None
        kn = get_var_name(key_var) if key_var else None
        vn = get_var_name(val_var) if val_var else None
        # Handle by_ref for val?
        return ForeachStmt(arr_expr, kn, vn, by_ref, body, t.line)

    def parse_switch(self):
        t=self.expect('ID')
        self.expect('OP','(')
        expr=self.parse_expr()
        self.expect('OP',')')
        # Expect { or : 
        cases=[]
        if self.match('OP','{'):
            # Parse case/default inside
            cur_cond=None
            cur_stmts=None
            # Switch body is list of case labels and stmts
            # We'll parse as: (case expr: stmts)* 
            pending=[]
            while not (self.peek().typ=='OP' and self.peek().val=='}'):
                if self.peek().typ=='EOF':
                    break
                if self.peek().typ=='ID' and self.peek().val.lower()=='case':
                    # Save previous?
                    if cur_stmts is not None or cur_cond is not None:
                        cases.append((cur_cond, Block(cur_stmts if cur_stmts else [])))
                    self.next()
                    c=self.parse_expr()
                    # expect : or ;
                    if not (self.match('OP',':') or self.match('OP',';')):
                        raise PhpParseError('syntax error, unexpected '+self.peek().val, self.file, self.peek().line)
                    cur_cond=c
                    cur_stmts=[]
                elif self.peek().typ=='ID' and self.peek().val.lower()=='default':
                    if cur_stmts is not None or cur_cond is not None:
                        cases.append((cur_cond, Block(cur_stmts if cur_stmts else [])))
                    self.next()
                    if not (self.match('OP',':') or self.match('OP',';')):
                        raise PhpParseError('syntax error', self.file, self.peek().line)
                    cur_cond=None
                    cur_stmts=[]
                else:
                    if cur_stmts is None:
                        # stmts before any case? Allow?
                        cur_stmts=[]
                        cur_cond='__before__'
                    if self.match('OP',';'):
                        continue
                    cur_stmts.append(self.parse_statement())
            if cur_stmts is not None or cur_cond is not None:
                # Handle __before__?
                if cur_cond=='__before__':
                    # Prepend? Actually ignore?
                    pass
                else:
                    cases.append((cur_cond, Block(cur_stmts if cur_stmts else [])))
            self.expect('OP','}')
        elif self.match('OP',':'):
            # Alternative syntax
            while not (self.peek().typ=='ID' and self.peek().val.lower()=='endswitch'):
                if self.peek().typ=='EOF':
                    break
                if self.peek().typ=='ID' and self.peek().val.lower()=='case':
                    self.next()
                    c=self.parse_expr()
                    if not (self.match('OP',':') or self.match('OP',';')):
                        raise PhpParseError('syntax error', self.file, self.peek().line)
                    s=[]
                    while True:
                        pt=self.peek()
                        if pt.typ=='ID' and pt.val.lower() in ('case','default','endswitch'):
                            break
                        if pt.typ=='EOF':
                            break
                        if self.match('OP',';'):
                            continue
                        s.append(self.parse_statement())
                    cases.append((c, Block(s)))
                elif self.peek().typ=='ID' and self.peek().val.lower()=='default':
                    self.next()
                    if not (self.match('OP',':') or self.match('OP',';')):
                        raise PhpParseError('syntax error', self.file, self.peek().line)
                    s=[]
                    while True:
                        pt=self.peek()
                        if pt.typ=='ID' and pt.val.lower() in ('case','default','endswitch'):
                            break
                        if pt.typ=='EOF':
                            break
                        if self.match('OP',';'):
                            continue
                        s.append(self.parse_statement())
                    cases.append((None, Block(s)))
                else:
                    if self.match('OP',';'):
                        continue
                    # stray?
                    self.parse_statement()
            if self.peek().typ=='ID':
                self.next()
            self.match('OP',';')
        else:
            raise PhpParseError('syntax error, unexpected '+self.peek().val, self.file, self.peek().line)
        return SwitchStmt(expr, cases, t.line)

    def parse_function_def(self):
        t=self.expect('ID')
        # Check for &?
        is_ref=False
        if self.match('OP','&'):
            is_ref=True
        name=None
        if self.peek().typ=='ID':
            name=self.next().val
        self.expect('OP','(')
        params=[]
        while not (self.peek().typ=='OP' and self.peek().val==')'):
            # Param: [type] [&] [...] $var [= default]
            # Skip type hints? Consume until $?
            by_ref=False
            variadic=False
            # Handle ...?
            if self.match('OP','...'):
                variadic=True
            # Handle &?
            if self.match('OP','&'):
                by_ref=True
            if self.match('OP','...'):
                variadic=True
            # Expect VAR
            if self.peek().typ=='VAR':
                v=self.next().val[1:]
            elif self.peek().typ=='DOLLAR':
                # $$? Not in params
                raise PhpParseError('syntax error', self.file, self.peek().line)
            else:
                # Might be type + var? e.g., int $x, ?string $x, array $x, callable $x
                # Skip type tokens until VAR
                # Consume ID, ?, \, |, &, etc.
                # For simplicity, skip ahead until VAR
                skipped=False
                while self.peek().typ in ('ID','OP') and not (self.peek().typ=='VAR'):
                    # Check for & and ...?
                    if self.peek().typ=='OP' and self.peek().val=='&':
                        self.next()
                        by_ref=True
                        continue
                    if self.peek().typ=='OP' and self.peek().val=='...':
                        self.next()
                        variadic=True
                        continue
                    if self.peek().typ=='VAR':
                        break
                    # If OP is ?, |, \, etc., skip
                    if self.peek().typ=='OP' and self.peek().val in ('?','|','&','\\'):
                        self.next()
                        continue
                    if self.peek().typ=='ID':
                        self.next()
                        skipped=True
                        continue
                    break
                if self.peek().typ=='VAR':
                    v=self.next().val[1:]
                else:
                    raise PhpParseError('syntax error, unexpected '+self.peek().val, self.file, self.peek().line)
            default=None
            has_default=False
            if self.match('OP','='):
                default=self.parse_expr()
                has_default=True
            params.append((v, default, has_default, by_ref, variadic))
            if not self.match('OP',','):
                break
        self.expect('OP',')')
        # Return type? : type
        if self.match('OP',':'):
            # Skip return type (could be ?type, |, etc.)
            # Consume until { or ;
            # For simplicity, skip tokens until { 
            while not (self.peek().typ=='OP' and self.peek().val in ('{',';')):
                if self.peek().typ=='EOF':
                    break
                self.next()
        if self.peek().typ=='OP' and self.peek().val==';':
            self.next()
            body=Block([])
        else:
            body=self.parse_block()
        return FunctionDef(name, params, body, t.line, is_ref)

    def parse_class_def(self):
        t=self.next()  # class/interface/trait/enum
        kind=t.val.lower()
        name=None
        if self.peek().typ=='ID':
            name=self.next().val
        parent=None
        interfaces=[]
        if self.peek().typ=='ID' and self.peek().val.lower()=='extends':
            self.next()
            if self.peek().typ=='ID':
                parent=self.next().val
                # Handle \?
                while self.match('OP','\\'):
                    if self.peek().typ=='ID':
                        parent+='\\'+self.next().val
        if self.peek().typ=='ID' and self.peek().val.lower()=='implements':
            self.next()
            while True:
                if self.peek().typ=='ID':
                    interfaces.append(self.next().val)
                    if not self.match('OP',','):
                        break
                else:
                    break
        self.expect('OP','{')
        # Parse class body: properties, methods, consts
        # For simplicity, collect raw statements? Actually class body contains method defs, property defs
        # We'll parse as list of nodes: FunctionDef for methods, etc.
        # Instead of full, store tokens and let runtime handle? Simpler: parse methods as FunctionDef, properties as assignments
        # We'll create a list of body_stmts by parsing until }
        body=[]
        while not (self.peek().typ=='OP' and self.peek().val=='}'):
            if self.peek().typ=='EOF':
                break
            if self.match('OP',';'):
                continue
            pt=self.peek()
            if pt.typ=='ID' and pt.val.lower() in ('public','private','protected','static','abstract','final','readonly','var','const','function'):
                # Could be method or property
                # Look ahead for 'function' or 'const' or VAR or ID?
                # Save modifiers
                mods=[]
                while self.peek().typ=='ID' and self.peek().val.lower() in ('public','private','protected','static','abstract','final','readonly','var'):
                    mods.append(self.next().val.lower())
                if self.peek().typ=='ID' and self.peek().val.lower()=='const':
                    # const X = val;
                    self.next()
                    # const name
                    if self.peek().typ=='ID':
                        cname=self.next().val
                        cval=None
                        if self.match('OP','='):
                            cval=self.parse_expr()
                        self.match('OP',';')
                        # Store as special?
                        body.append(('const', cname, cval, mods))
                    continue
                if self.peek().typ=='ID' and self.peek().val.lower()=='function':
                    f=self.parse_function_def()
                    # Attach mods?
                    body.append(('method', f, mods))
                    continue
                # Otherwise property: [type] $var [= val], ...
                # Parse properties
                # Skip type?
                # For simplicity, parse VAR list
                props=[]
                while True:
                    # Skip type ID?
                    # If next is VAR, good
                    if self.peek().typ=='VAR':
                        vname=self.next().val[1:]
                        dval=None
                        has=False
                        if self.match('OP','='):
                            dval=self.parse_expr()
                            has=True
                        props.append((vname,dval,has))
                    elif self.peek().typ=='ID':
                        # Type, skip
                        self.next()
                        continue
                    else:
                        break
                    if not self.match('OP',','):
                        break
                self.match('OP',';')
                for pn,pd,ph in props:
                    body.append(('prop', pn, pd, ph, mods))
                continue
            elif pt.typ=='ID' and pt.val.lower()=='use':
                # trait use
                self.next()
                # skip until ;
                while not (self.peek().typ=='OP' and self.peek().val in (';','{')):
                    if self.peek().typ=='EOF':
                        break
                    self.next()
                if self.peek().typ=='OP' and self.peek().val=='{':
                    # trait adaptations? skip block
                    depth=0
                    while True:
                        tt=self.next()
                        if tt.typ=='OP' and tt.val=='{':
                            depth+=1
                        if tt.typ=='OP' and tt.val=='}':
                            if depth==0:
                                break
                            depth-=1
                        if tt.typ=='EOF':
                            break
                else:
                    self.match('OP',';')
                continue
            else:
                # Unknown, skip?
                # Try to parse as statement? But class body shouldn't have statements
                # Skip token
                self.next()
        self.expect('OP','}')
        return ClassDef(name, parent, interfaces, body, t.line)

    def parse_return(self):
        t=self.expect('ID')
        if self.peek().typ=='OP' and self.peek().val==';':
            self.next()
            return ReturnStmt(None, t.line)
        expr=self.parse_expr()
        self.match('OP',';')
        return ReturnStmt(expr, t.line)

    def parse_break(self):
        t=self.expect('ID')
        lvl=None
        if not (self.peek().typ=='OP' and self.peek().val==';'):
            lvl=self.parse_expr()
        self.match('OP',';')
        return BreakStmt(lvl, t.line)

    def parse_continue(self):
        t=self.expect('ID')
        lvl=None
        if not (self.peek().typ=='OP' and self.peek().val==';'):
            lvl=self.parse_expr()
        self.match('OP',';')
        return ContinueStmt(lvl, t.line)

    def parse_try(self):
        t=self.expect('ID')
        body=self.parse_block()
        catches=[]
        finally_b=None
        while self.peek().typ=='ID' and self.peek().val.lower()=='catch':
            self.next()
            self.expect('OP','(')
            # catch (Class $var) or catch (Class1|Class2 $var)?
            cls_names=[]
            while True:
                if self.peek().typ=='ID':
                    cls_names.append(self.next().val)
                    if self.match('OP','|'):
                        continue
                    # Handle \?
                    while self.match('OP','\\'):
                        if self.peek().typ=='ID':
                            cls_names[-1]+='\\'+self.next().val
                    if self.match('OP','|'):
                        continue
                    break
                else:
                    break
            var=None
            if self.peek().typ=='VAR':
                var=self.next().val[1:]
            self.expect('OP',')')
            cb=self.parse_block()
            for cn in cls_names:
                catches.append((cn, var, cb))
            # If no class? catch without? 
        if self.peek().typ=='ID' and self.peek().val.lower()=='finally':
            self.next()
            finally_b=self.parse_block()
        return TryStmt(body, catches, finally_b, t.line)

    def parse_throw(self):
        t=self.expect('ID')
        # throw is expression in PHP 8? But also statement
        expr=self.parse_expr()
        self.match('OP',';')
        return ThrowStmt(expr, t.line)

    def parse_include_stmt(self):
        t=self.next()
        kind=t.val.lower()
        once=False
        if kind in ('include_once','require_once'):
            once=True
            kind=kind.replace('_once','')
        # include expr; or include(expr);
        # Check for '('?
        expr=self.parse_expr()
        self.match('OP',';')
        return IncludeStmt(kind, expr, t.line, once)

    def parse_global(self):
        t=self.expect('ID')
        vars=[]
        while True:
            if self.peek().typ=='VAR':
                vars.append(self.next().val[1:])
            else:
                raise PhpParseError('syntax error', self.file, self.peek().line)
            if not self.match('OP',','):
                break
        self.match('OP',';')
