                self.next()
                expr=UnaryExpr('++', expr, t.line, prefix=False)
            elif t.typ=='OP' and t.val=='--':
                self.next()
                expr=UnaryExpr('--', expr, t.line, prefix=False)
            elif t.typ=='OP' and t.val=='[':
                self.next()
                idx=None
                if not (self.peek().typ=='OP' and self.peek().val==']'):
                    idx=self.parse_expr()
                self.expect('OP',']')
                expr=ArrayAccessExpr(expr, idx, t.line)
            elif t.typ=='OP' and t.val=='->':
                self.next()
                # method or prop? Check if next is ID and then '('?
                nullsafe=False
                # Actually -> vs ?-> (nullsafe)
                # Our lexer gives '?.' for ?->? No, we have '?.' but PHP nullsafe is ?->
                # Our lexer doesn't handle ?-> correctly. Handle: if previous was '?'? No.
                # For simplicity, handle ?-> as two tokens? Actually code '?->' would be lexed as '?' then '->'? Our lexer gives '?.' for '?.', not '?->'.
                # Let's handle: if next is ID
                if self.peek().typ=='ID':
                    name=self.next().val
                    if self.peek().typ=='OP' and self.peek().val=='(':
                        # method call
                        args=self.parse_args()
                        expr=MethodCallExpr(expr, name, args, t.line)
                    else:
                        # property, possibly with array access? Handle later
                        expr=PropAccessExpr(expr, name, t.line)
                        # Check for array access after? Will be handled in loop
                elif self.peek().typ=='VAR':
                    # $$? Actually $obj->$var
                    v=self.next().val[1:]
                    # Could be method if '(' after?
                    # For simplicity, treat as prop with dynamic name
                    expr=PropAccessExpr(expr, VarExpr(v, t.line), t.line)
                elif self.peek().typ=='OP' and self.peek().val=='{':
                    # $obj->{$expr}
                    self.next()
                    e=self.parse_expr()
                    self.expect('OP','}')
                    expr=PropAccessExpr(expr, e, t.line)
                else:
                    raise PhpParseError('syntax error, unexpected '+self.peek().val, self.file, self.peek().line)
            elif t.typ=='OP' and t.val=='::':
                self.next()
                # static call or const or var?
                # Next could be ID, VAR, $, etc.
                if self.peek().typ=='ID':
                    name=self.next().val
                    if self.peek().typ=='OP' and self.peek().val=='(':
                        args=self.parse_args()
                        # cls is expr (could be ID, var, etc.)
                        expr=StaticCallExpr(expr, name, args, t.line)
                    else:
                        # class const or static prop? For simplicity, treat as static call with no args? Actually Class::CONST
                        # We'll create StaticCallExpr with empty args? Or Prop?
                        # Check for $?
                        if name.startswith('$'):
                            pass
                        expr=StaticCallExpr(expr, name, [], t.line)
                elif self.peek().typ=='VAR':
                    v=self.next().val
                    expr=StaticCallExpr(expr, v, [], t.line)
                elif self.peek().typ=='OP' and self.peek().val=='$':
                    # ::$var?
                    self.next()
                    if self.peek().typ=='ID':
                        n=self.next().val
                        expr=StaticCallExpr(expr, '$'+n, [], t.line)
                    else:
                        raise PhpParseError('syntax error', self.file, self.peek().line)
                else:
                    raise PhpParseError('syntax error', self.file, self.peek().line)
            elif t.typ=='OP' and t.val=='(':
                # function call: expr(...)
                args=self.parse_args()
                expr=CallExpr(expr, args, t.line)
            else:
                break
        return expr

    def parse_args(self):
        self.expect('OP','(')
        args=[]
        while not (self.peek().typ=='OP' and self.peek().val==')'):
            # Handle ... unpack?
            unpack=False
            if self.match('OP','...'):
                unpack=True
            # Handle &? For call, & not needed
            # Handle named args? Name: value? Check ID followed by :?
            # Look ahead: ID ':' ?
            if self.peek().typ=='ID' and self.peek(1).typ=='OP' and self.peek(1).val==':':
                # named arg, skip name?
                self.next()
                self.next()
                e=self.parse_expr()
                args.append((e, unpack))
            else:
                e=self.parse_expr()
                args.append((e, unpack))
            if not self.match('OP',','):
                break
        self.expect('OP',')')
        return args

    def parse_primary(self):
        t=self.peek()
        if t.typ=='NUMBER':
            self.next()
            raw=t.val.replace('_','')
            if raw.lower().startswith('0x'):
                val=int(raw,16)
            elif raw.lower().startswith('0b'):
                val=int(raw,2)
            elif raw.lower().startswith('0') and len(raw)>1 and raw[1].isdigit():
                # octal? PHP 0 prefix is octal if valid, else decimal? Simplify as octal
                try:
                    val=int(raw,8)
                except:
                    val=int(raw)
            elif '.' in raw or 'e' in raw.lower():
                val=float(raw)
            else:
                val=int(raw)
            return ConstExpr(val, t.line)
        if t.typ=='STRING':
            self.next()
            raw=t.val
            # Process string
            if raw[0]=="'":
                # Single quoted: only \\ and \' 
                inner=raw[1:-1]
                inner=inner.replace("\\\\","\x00").replace("\\'","'").replace("\x00","\\")
                # Also \n not interpreted? Actually single quotes don't interpret \n
                return ConstExpr(inner, t.line)
            else:
                # Double quoted: handle escapes and interpolation
                inner=raw[1:-1]
                # Unescape
                # PHP escapes: \n \r \t \v \e \f \\ \$ \" \0..\ etc.
                # For simplicity, handle common
                def unesc(s):
                    s=s.replace("\\n","\n").replace("\\r","\r").replace("\\t","\t").replace("\\v","\v").replace("\\e","\x1b").replace("\\f","\f").replace("\\\\","\x00").replace('\\"','"').replace("\\$","$").replace("\\0","\0")
                    s=s.replace("\x00","\\")
                    # Handle \$? Already
                    # Handle octal/hex? Skip
                    return s
                # Check for interpolation: $var, {$var}, ${var}, {$expr}?
                # If contains $, need to return interpolated expression (concat)
                if '$' in inner or '{' in inner:
                    # Parse interpolation into concat of strings and vars
                    # We'll build a BinaryExpr chain with '.' 
                    parts=self.parse_double_string(inner, t.line)
                    if parts is None:
                        return ConstExpr(unesc(inner), t.line)
                    else:
                        return parts
                else:
                    return ConstExpr(unesc(inner), t.line)
        if t.typ=='VAR':
            self.next()
            return VarExpr(t.val[1:], t.line)
        if t.typ=='DOLLAR':
            # $$var or $${expr}
            self.next()
            # Next should be VAR or { or $?
            if self.peek().typ=='VAR':
                v=self.next()
                # $$b where b is var name? Actually $$b means variable variable with name = value of $b
                return VarVarExpr(VarExpr(v.val[1:], v.line), t.line)
            elif self.peek().typ=='OP' and self.peek().val=='{':
                self.next()
                e=self.parse_expr()
                self.expect('OP','}')
                return VarVarExpr(e, t.line)
            elif self.peek().typ=='DOLLAR':
                # $$$?
                e=self.parse_primary()
                return VarVarExpr(e, t.line)
            else:
                # $ followed by ID? e.g., $ foo? Actually ${...}?
                raise PhpParseError('syntax error, unexpected '+self.peek().val, self.file, self.peek().line)
        if t.typ=='ID':
            low=t.val.lower()
            if low in ('true','false'):
                self.next()
                return ConstExpr(True if low=='true' else False, t.line)
            if low in ('null',):
                self.next()
                return ConstExpr(None, t.line)
            if low=='array':
                # array(...) or array[...]?
                self.next()
                if self.peek().typ=='OP' and self.peek().val=='(':
                    self.next()
                    pairs=self.parse_array_pairs(')')
                    self.expect('OP',')')
                    return ArrayExpr(pairs, t.line)
                else:
                    return ConstExpr(t.val, t.line)
            if low in ('isset',):
                self.next()
                self.expect('OP','(')
                exprs=[]
                while True:
                    exprs.append(self.parse_expr())
                    if not self.match('OP',','):
                        break
                self.expect('OP',')')
                return IssetExpr(exprs, t.line)
            if low=='empty':
                self.next()
                self.expect('OP','(')
                e=self.parse_expr()
                self.expect('OP',')')
                return EmptyExpr(e, t.line)
            if low=='unset':
                # unset(...) as expression? Actually statement, but handle
                self.next()
                self.expect('OP','(')
                exprs=[]
                while True:
                    exprs.append(self.parse_expr())
                    if not self.match('OP',','):
                        break
                self.expect('OP',')')
                return UnsetStmt(exprs, t.line)
            if low in ('include','include_once','require','require_once'):
                self.next()
                once='once' in low
                kind='include' if 'include' in low else 'require'
                # include may have parens or not
                if self.peek().typ=='OP' and self.peek().val=='(':
                    # Could be include('file')? Parse as expr in parens?
                    # For simplicity, parse expr
                    e=self.parse_expr()
                else:
                    e=self.parse_expr()
                return IncludeExpr(kind, e, t.line, once)
            if low in ('exit','die'):
                self.next()
                e=None
                if self.peek().typ=='OP' and self.peek().val=='(':
                    self.next()
                    if not (self.peek().typ=='OP' and self.peek().val==')'):
                        e=self.parse_expr()
                    self.expect('OP',')')
                elif not (self.peek().typ=='OP' and self.peek().val in (';',' )',')',',',']')):
                    # exit without parens? e.g., exit 5; ?
                    # Only if next is not delimiter
                    pass
                return ExitExpr(e, t.line)
            if low=='print':
                self.next()
                e=self.parse_expr()
                return PrintExpr(e, t.line)
            if low=='clone':
                self.next()
                e=self.parse_expr()
                return CloneExpr(e, t.line)
            if low=='new':
                self.next()
                # Class name: ID, VAR, etc.
                if self.peek().typ=='ID':
                    cls=self.next().val
                    # Handle \?
                    while self.match('OP','\\'):
                        if self.peek().typ=='ID':
                            cls+='\\'+self.next().val
                elif self.peek().typ=='VAR':
                    cls=self.parse_expr()
                else:
                    cls=self.parse_expr()
                args=[]
                if self.peek().typ=='OP' and self.peek().val=='(':
                    args=self.parse_args()
                return NewExpr(cls, args, t.line)
            if low=='function':
                # Anonymous function
                return self.parse_closure()
            if low=='fn':
                return self.parse_arrow()
            if low=='match':
                return self.parse_match()
            if low=='yield':
                # Simplify: treat as null?
                self.next()
                if self.peek().typ=='OP' and self.peek().val in (';',' )',')',','):
                    return ConstExpr(None, t.line)
                e=self.parse_expr()
                return e
            if low in ('__line__',):
                self.next()
                return ConstExpr(t.line, t.line)  # Will be replaced with actual line? For now line
            if low in ('__file__',):
                self.next()
                return ConstExpr(self.file, t.line)
            if low in ('__dir__',):
                self.next()
                # Dir of file
                import os as _os
                d=_os.path.dirname(self.file) if self.file not in ('Command line code','Standard input code','Command line run code') else '.'
                return ConstExpr(d, t.line)
            if low in ('__function__','__class__','__method__','__trait__','__namespace__'):
                self.next()
                return ConstExpr('', t.line)
            # Check for function call vs const vs class?
            # If next is '(' then call, else const/var?
            if self.peek(1).typ=='OP' and self.peek(1).val=='(':
                # function call
                name=t.val
                self.next()
                args=self.parse_args()
                # func is ID string
                return CallExpr(name, args, t.line)
            elif self.peek(1).typ=='OP' and self.peek(1).val=='::':
                # static? Will be handled in postfix? Actually primary is ID, then postfix handles ::
                # So just return const ID and let postfix handle?
                self.next()
                base=t.val
                # Don't consume ::, let postfix handle? But postfix expects expr then ::, so base as ConstExpr?
                # For simplicity, return ConstExpr for class name and let postfix? No, postfix needs left expr.
                # We'll return a special node for class name?
                # Instead, create a ConstExpr with class name and let caller handle? But our parse_postfix already handles :: after primary.
                # So return ConstExpr and rewind? Actually we already consumed ID, need to put back :: handling.
                # Our parse_postfix will handle :: after returning primary, so just return ID as ConstExpr and not consume ::.
                return ConstExpr(base, t.line)
            else:
                # Constant or bare string?
                self.next()
                # Check if it's a known constant? Will be resolved at runtime
                return CallExpr('__const__', [(ConstExpr(t.val, t.line), False)], t.line)  # Special to fetch constant?
                # Actually better to return a ConstFetch node
        if t.typ=='OP' and t.val=='(':
            self.next()
            e=self.parse_expr()
            self.expect('OP',')')
            return e
        if t.typ=='OP' and t.val=='[':
            self.next()
            pairs=self.parse_array_pairs(']')
            self.expect('OP',']')
            return ArrayExpr(pairs, t.line)
        # Handle ...? Not here
        raise PhpParseError(f'syntax error, unexpected {t.val!r}', self.file, t.line)

    def parse_array_pairs(self, end):
        pairs=[]
        while not (self.peek().typ=='OP' and self.peek().val==end):
            if self.peek().typ=='EOF':
                break
            # Handle ,?
            if self.match('OP',','):
                continue
            # Handle ... unpack?
            if self.match('OP','...'):
                e=self.parse_expr()
                pairs.append((None, e, False, True))
                if not self.match('OP',','):
                    # continue
                    pass
                continue
            # Handle &?
            by_ref=False
            if self.match('OP','&'):
                by_ref=True
            # Try to parse key => value or value
            # Need to look ahead for =>?
            # Save pos, parse expr, check for =>?
            save=self.pos
            try:
                e1=self.parse_expr()
            except:
                raise
            if self.peek().typ=='OP' and self.peek().val=='=>':
                self.next()
                # Check for & and ...?
                by_ref2=False
                unpack=False
                if self.match('OP','...'):
                    unpack=True
                if self.match('OP','&'):
                    by_ref2=True
                e2=self.parse_expr()
                pairs.append((e1, e2, by_ref2, unpack))
            else:
                # e1 is value, key None
                # Check if e1 was &? Already handled? If by_ref and e1 is var, then it's by-ref value?
                pairs.append((None, e1, by_ref, False))
            if not self.match('OP',','):
                # Continue loop, will check end
                pass
        return pairs

    def parse_double_string(self, inner, line):
        # Parse double-quoted string with interpolation into concat expression
        # inner is without quotes, with escapes still? Need to handle $var, {$...}, ${...}
        # For simplicity, scan for $ and build parts
        parts=[]  # list of (is_expr, content)
        i=0
        n=len(inner)
        cur=""
        while i<n:
            c=inner[i]
            if c=='\\' and i+1<n:
                nxt=inner[i+1]
                if nxt in ('n','r','t','v','e','f','\\','"','$'):
                    # Keep as is for later unescape? Actually we need to handle escapes in literal parts
                    # Append raw escape to cur, will unescape later
                    cur+=c+nxt
                    i+=2
                    continue
                else:
                    cur+=c
                    i+=1
                    continue
            if c=='$' and i+1<n:
                # Check for $var, ${var}, ${expr}, {$...}?
                if inner[i+1]=='{':
                    # ${...} or {$...}? Actually $ followed by { is ${...}
                    # Find matching }
                    j=inner.find('}', i+2)
                    if j==-1:
                        cur+='$'
                        i+=1
                        continue
                    expr_str=inner[i+2:j]
                    # Flush cur
                    if cur:
                        parts.append(('str', cur))
                        cur=""
                    # Parse expr_str as PHP expr? For ${var} it's var, for ${expr}?
                    # Simplify: if expr_str is var name, treat as var, else parse?
                    # We'll create a VarExpr if it's simple name, else parse via tokenize?
                    m=re.match(r'^[a-zA-Z_\x80-\xff][a-zA-Z0-9_\x80-\xff]*$', expr_str)
                    if m:
                        parts.append(('expr', VarExpr(expr_str, line)))
                    else:
                        # Try to parse as expr by tokenizing?
                        try:
                            toks=tokenize(expr_str, line)
                            p2=Parser(toks, self.file)
                            e2=p2.parse_expr()
                            parts.append(('expr', e2))
                        except:
                            parts.append(('str', '${'+expr_str+'}'))
                    i=j+1
                    continue
                else:
                    m=re.match(r'\$[a-zA-Z_\x80-\xff][a-zA-Z0-9_\x80-\xff]*', inner[i:])
                    if m:
                        if cur:
                            parts.append(('str', cur))
                            cur=""
                        var_name=m.group(0)[1:]
                        # Check for array access or -> after? e.g., "$a[0]", "$a->b", "$a->b[0]"?
                        # For simplicity, handle $var followed by [..] or ->..?
                        rest_start=i+len(m.group(0))
                        # Look ahead for [ or ->
                        # We'll parse extended?
                        # Check for ->?
                        # This is complex; for now, just handle simple $var, and let following chars be literal? But "$a[0]" should interpolate $a[0], not $a + "[0]"
                        # Let's try to handle: if next is '[', parse index?
                        # We'll peek ahead in inner string for '['
                        # Simplify: check if rest_start < n and inner[rest_start]=='['
                        # Then find matching ] and include?
                        # Similarly for ->?
                        # For now, handle $var[..] and $var->prop
                        extra=""
                        j=rest_start
                        # Handle ->?
                        # This is getting complex; we'll implement basic: $var, $var[expr], $var->prop
                        # Use regex for $var(\[[^\]]*\]|->[a-zA-Z_][a-zA-Z0-9_]*)*
                        # But need to handle nested? Simplify
                        # Let's just take $var and leave rest as literal; tests with "$k:$v" will work (simple vars)
                        parts.append(('expr', VarExpr(var_name, line)))
                        i=rest_start
                        # Check for [ or -> and include as part of expr? For "$a[0]", our simple will produce $a + "[0]" which is wrong (would output "1[0]"? Actually $a is array, to string? Hmm)
                        # But typical interpolation is "$k:$v" which is simple vars, so fine.
                        # For array interpolation like "$a[0]", we need to handle. Let's try to handle one level:
                        if j<n and inner[j]=='[':
                            # Find ]
                            k2=inner.find(']', j)
                            if k2!=-1:
                                idx_str=inner[j+1:k2]
                                # idx could be number, quoted string, or var?
                                # Create ArrayAccessExpr
                                # Pop last expr (var) and replace with array access
                                last=parts.pop()
                                # Parse idx
                                idx_expr=None
                                idx_str=idx_str.strip()
                                if idx_str.isdigit():
                                    idx_expr=ConstExpr(int(idx_str), line)
                                elif idx_str.startswith("'") or idx_str.startswith('"'):
                                    # quoted?
                                    q=idx_str[0]
                                    idx_expr=ConstExpr(idx_str[1:-1], line)
                                elif idx_str.startswith('$'):
                                    idx_expr=VarExpr(idx_str[1:], line)
                                else:
                                    idx_expr=ConstExpr(idx_str, line)
                                parts.append(('expr', ArrayAccessExpr(last[1], idx_expr, line)))
                                i=k2+1
                                continue
                        # Handle ->?
                        if j+1<n and inner[j:j+2]=='->':
                            m2=re.match(r'->[a-zA-Z_\x80-\xff][a-zA-Z0-9_\x80-\xff]*', inner[j:])
                            if m2:
                                last=parts.pop()
                                prop=m2.group(0)[2:]
                                parts.append(('expr', PropAccessExpr(last[1], prop, line)))
                                i=j+len(m2.group(0))
                                continue
                        continue
                    else:
                        cur+='$'
                        i+=1
                        continue
            elif c=='{' and i+1<n and inner[i+1]=='$':
                # {$var}?
                j=inner.find('}', i)
                if j==-1:
                    cur+=c
                    i+=1
                    continue
                expr_str=inner[i+1:j]  # includes $?
                if cur:
                    parts.append(('str', cur))
                    cur=""
                # Parse expr_str (e.g., $var, $var[0], etc.)
                try:
                    toks=tokenize(expr_str, line)
                    p2=Parser(toks, self.file)
                    e2=p2.parse_expr()
                    parts.append(('expr', e2))
                except:
                    parts.append(('str', inner[i:j+1]))
                i=j+1
                continue
            else:
                cur+=c
                i+=1
        if cur:
            parts.append(('str', cur))
        if not parts:
            return ConstExpr("", line)
        # If only one str part and no expr, return ConstExpr
        if len(parts)==1 and parts[0][0]=='str':
            # Unescape
            s=parts[0][1]
            s=s.replace("\\n","\n").replace("\\r","\r").replace("\\t","\t").replace("\\v","\v").replace("\\e","\x1b").replace("\\f","\f").replace("\\\\","\x00").replace('\\"','"').replace("\\$","$")
            s=s.replace("\x00","\\")
            return ConstExpr(s, line)
        # Build concat expression: parts with '.' 
        # For str parts, unescape and make ConstExpr; for expr parts, keep
        expr=None
        for kind, content in parts:
            if kind=='str':
                s=content.replace("\\n","\n").replace("\\r","\r").replace("\\t","\t").replace("\\v","\v").replace("\\e","\x1b").replace("\\f","\f").replace("\\\\","\x00").replace('\\"','"').replace("\\$","$")
                s=s.replace("\x00","\\")
                node=ConstExpr(s, line)
            else:
                node=content
            if expr is None:
                expr=node
            else:
                expr=BinaryExpr('.', expr, node, line)
        return expr

    def parse_closure(self):
        t=self.expect('ID')  # function
        if self.match('OP','&'):
            pass
        self.expect('OP','(')
        params=[]
        while not (self.peek().typ=='OP' and self.peek().val==')'):
            by_ref=False
            variadic=False
            if self.match('OP','...'):
                variadic=True
            if self.match('OP','&'):
                by_ref=True
            if self.match('OP','...'):
                variadic=True
            if self.peek().typ=='VAR':
                v=self.next().val[1:]
            else:
                # Skip type?
                while self.peek().typ in ('ID','OP') and self.peek().typ!='VAR':
                    if self.peek().typ=='OP' and self.peek().val=='&':
                        self.next()
                        by_ref=True
                        continue
                    if self.peek().typ=='OP' and self.peek().val=='...':
                        self.next()
                        variadic=True
                        continue
                    if self.peek().typ=='OP' and self.peek().val in ('?','|','\\'):
                        self.next()
                        continue
                    if self.peek().typ=='ID':
                        self.next()
                        continue
                    break
                if self.peek().typ=='VAR':
                    v=self.next().val[1:]
                else:
                    raise PhpParseError('syntax error', self.file, self.peek().line)
            default=None
            has=False
            if self.match('OP','='):
                default=self.parse_expr()
                has=True
            params.append((v,default,has,by_ref,variadic))
            if not self.match('OP',','):
                break
        self.expect('OP',')')
        uses=[]
        if self.peek().typ=='ID' and self.peek().val.lower()=='use':
            self.next()
            self.expect('OP','(')
            while not (self.peek().typ=='OP' and self.peek().val==')'):
                by_ref=False
                if self.match('OP','&'):
                    by_ref=True
                if self.peek().typ=='VAR':
                    uses.append((self.next().val[1:], by_ref))
                if not self.match('OP',','):
                    break
            self.expect('OP',')')
        # Return type?
        if self.match('OP',':'):
